type ModuleContract = { id: string; backend: { endpoint: string; createEndpoint?: string }; fields: ContractField[]; requiredFields: string[]; relationships?: { field: string; target: string }[]; permissions?: { write?: string[]; read?: string[] }; validation?: { rejectBlankStrings?: boolean; rejectInvalidIds?: boolean; organizationScoped?: boolean; backendIndependent?: boolean }; emptyState?: { message?: string } }; 

const API=(process.env.NEXT_PUBLIC_API_URL||'https://clinai-api.onrender.com').replace(/\/$/,'');

async function fetchJSON(url:string, init:RequestInit={}, token?:string){
 const headers=new Headers(init.headers||{});
 if(!headers.has('Accept')) headers.set('Accept','application/json');
 if(token) headers.set('Authorization',`Bearer ${token}`);
 const response=await fetch(url,{...init,headers});
 const contentType=response.headers.get('content-type')||'';
 let data:any={};
 if(contentType.includes('application/json')){
  try{data=await response.json()}catch{data={}}
 }else{
  const text=await response.text();
  data=text?{error:text}:{};
 }
 return {r:response,data};
}


