function PublicCommandCenter({setModule,setPublicPatient,openPatient,openPublicPatient}:{setModule:(m:string)=>void;setPublicPatient:(p:string)=>void;openPatient:(p:string)=>void;openPublicPatient:(p:string)=>void}){const [data,setData]=useState<Row>({});const [selected,setSelected]=useState('');const [patients,setPatients]=useState<Row[]>([]);useEffect(()=>{fetch(`${API}/api/public/test-dashboard`).then(r=>r.json()).then(d=>setData(d.data||{})).catch(()=>{});fetch(`${API}/api/public/test-patients`).then(r=>r.json()).then(d=>setPatients(d.data||[])).catch(()=>{})},[]);const o=data.overview||{};return <div className="command-center public-command-center"><section className="welcome-panel public-welcome-panel"><div><span className="section-kicker">CLINAI TEST ENVIRONMENT</span><h2>Care, clearly in view.</h2><p>This public workspace uses test patient records so you can explore connected care, Patient 360, analytics and ClinAI intelligence.</p><div className="public-command-actions"><button className="primary" onClick={()=>setModule('ai')}>Test ClinAI AI</button><PublicFeedbackButton/></div></div><div className="welcome-mark"><img src="/clinai-icon.png" alt="ClinAI"/></div></section><div className="test-data-banner"><strong>TEST DATA</strong><span>All patients shown here are test records created for ClinAI evaluation. They are not real patient records.</span></div><section className="public-kpi-grid">{[['Patients',o.patients],['Today',o.appointments_today],['Waiting',o.waiting],['Active care',o.active_encounters],['Critical results',(data.clinical||[]).find((x:Row)=>x.label==='Critical laboratory results')?.count||0],['Open tasks',o.open_tasks]].map(([label,value])=><div className="panel public-kpi" key={String(label)}><span>{label}</span><strong>{Number(value||0).toLocaleString()}</strong></div>)}</section><section className="public-dashboard-grid"><div className="panel"><div className="panel-title"><div><span className="section-kicker">ATTENTION CENTER</span><h2>What deserves review</h2></div></div>{(data.clinical||[]).map((x:Row)=><button className="public-attention-row" key={x.label} onClick={()=>setModule(x.label.includes('laboratory')?'laboratory':x.label.includes('task')?'care-tasks':x.label.includes('referral')?'referrals':'medication-reconciliation')}><span>{x.label}</span><strong>{x.count}</strong></button>)}</div><div className="panel"><div className="panel-title"><div><span className="section-kicker">PATIENT FLOW</span><h2>Where test patients are now</h2></div></div><div className="flow-pipeline">{(data.queue||[]).map((x:Row)=><div key={`${x.status}-${x.priority}`}><b>{x.count}</b><span>{pretty(x.status)}</span><small>{x.priority}</small></div>)}</div><div className="public-capacity"><span>Capacity</span><strong>{o.occupied_beds||0} occupied</strong><small>{o.available_beds||0} available</small></div></div></section><section className="panel public-patient-panel"><div className="panel-title"><div><span className="section-kicker">TEST PATIENTS</span><h2>Explore 30 connected patient records</h2><p>All 30 test patients are test records available for connected-care review.</p><p>Choose a synthetic patient to inspect the recorded problem and test ClinAI against the connected journey.</p></div><span className="journey-note-inline">{patients.length} patients</span></div><div className="public-patient-grid">{patients.map((p:Row)=><button key={p.patientNumber} className={`public-patient-card ${selected===p.patientNumber?'active':''}`} onClick={()=>{setSelected(p.patientNumber);setPublicPatient(p.patientNumber);openPublicPatient(p.patientNumber)}}><span>{p.patientNumber}</span><strong>{p.firstName} {p.lastName}</strong><small>{p.currentProblem||'Clinical test record'}</small><em>{p.priority||'routine'}</em></button>)}</div></section>{selected&&<section className="panel public-selected-patient"><div><span className="section-kicker">SELECTED TEST PATIENT</span><h2>{patients.find((p:Row)=>p.patientNumber===selected)?.firstName} {patients.find((p:Row)=>p.patientNumber===selected)?.lastName}</h2><p>{patients.find((p:Row)=>p.patientNumber===selected)?.currentProblem}</p></div><button className="ghost" onClick={()=>openPublicPatient(selected)}>Open Patient 360</button><button className="primary" onClick={()=>setModule('ai')}>Ask ClinAI about this patient</button></section>}<IntelligenceWorkspaceHub token="" publicMode publicTestPatientNumber={selected||undefined} setModule={setModule}/><section className="public-test-grid"><article><span>01</span><strong>Connected care</strong><p>Follow records across visits, diagnoses, investigations, medicines, referrals, tasks and finance.</p></article><article><span>02</span><strong>Patient 360</strong><p>Test how ClinAI brings the recorded patient story together.</p></article><article><span>03</span><strong>Analytics</strong><p>Explore patient flow, service pressure, capacity and care gaps using real relationships in the test dataset.</p></article><article><span>04</span><strong>Feedback</strong><p>Use WhatsApp to tell us what works, what is missing and what should change.</p></article></section></div>}

function CommandCenter({dash={},metrics=[],setModule,journey=[],token,publicTestPatient='',setPublicPatient=()=>{},openPatient,openPublicPatient,publicMode=false}:{dash?:Row;metrics?:any[];setModule:(m:string)=>void;journey?:any[];token:string;publicTestPatient?:string;setPublicPatient?:(p:string)=>void;openPatient:(p:string)=>void;openPublicPatient:(p:string)=>void;publicMode?:boolean}){
 const [intel,setIntel]=useState<Row>({overview:{patients:dash.patients||0,appointments_today:dash.appointments||0,waiting:dash.waiting||0,critical_labs:dash.criticalLabs||0,open_tasks:dash.openTasks||0}}); const [role,setRole]=useState('Authorized workspace');
 useEffect(()=>{if(!token)return;if(typeof window==='undefined')return;let cancelled=false;const load=()=>fetch(`${API}/api/analytics/command-center`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.json()).then(d=>{if(!cancelled)setIntel(d.data||{})}).catch(()=>{});const id:any='requestIdleCallback' in window?(window as any).requestIdleCallback(load,{timeout:1500}):setTimeout(load,40);return()=>{cancelled=true;if('cancelIdleCallback' in window&&typeof (window as any).cancelIdleCallback==='function')(window as any).cancelIdleCallback(id);else clearTimeout(id)}} , [token]);
 const o={patients:dash.patients||0,appointments_today:dash.appointments||0,waiting:dash.waiting||0,critical_labs:dash.criticalLabs||0,open_tasks:dash.openTasks||0,...(intel.overview||{})}; const trend=intel.trend||[]; const maxTrend=Math.max(1,...trend.map((x:Row)=>Number(x.appointments||0)));
 if(!token) return <PublicCommandCenter setModule={setModule} setPublicPatient={setPublicPatient} openPatient={openPatient} openPublicPatient={openPublicPatient}/>;
 const roleCards:Record<string,Array<[string,string,string]>>={Leadership:[['Today','patients and service pressure','analytics'],['Financial health','billing and collection','billing'],['Facility readiness','capacity and incidents','facilities']],Doctor:[['My care','active encounters and follow-up','encounters'],['Results','laboratory and imaging review','laboratory'],['Tasks','clinical work needing attention','care-tasks']],Nurse:[['Patient flow','triage and waiting','queue'],['Care tasks','observations and bedside work','nursing'],['Escalations','urgent patients and alerts','emergency']],Pharmacist:[['Dispensing','prescriptions waiting','pharmacy'],['Stock','items needing attention','inventory'],['Reviews','medication reconciliation','medication-reconciliation']]};
 const cards=roleCards[role]||roleCards.Leadership;
 return <div className="command-center">
  <section className="welcome-panel"><div><span className="section-kicker">COMMAND CENTER</span><h2>Care, clearly in view.</h2><p>See patient flow, clinical attention, financial pressure and facility readiness without opening separate screens.</p></div><div className="welcome-mark"><img src="/clinai-icon.png" alt="ClinAI"/></div></section>
  <section className="panel ai-command-card"><div><span className="section-kicker">CLINAI INTELLIGENCE</span><h2>What needs attention today?</h2><p>Ask ClinAI to interpret the current operational and clinical picture.</p></div><button className="primary" onClick={()=>setModule('ai')}>Ask ClinAI →</button></section>
  <section className="metric-grid command-kpis">{[['Patients',o.patients??dash.patients,'registered'],['Appointments',o.appointments_today??dash.appointments,'today'],['Waiting',o.waiting??dash.waiting,'in care flow'],['Active care',o.active_encounters??0,'consultations'],['Beds occupied',o.occupied_beds??0,'inpatient'],['Open tasks',o.open_tasks??dash.openTasks,'need attention']].map(([n,v,s],i)=><div className={`metric-card metric-${i}`} key={String(n)}><span>{n}</span><strong>{v}</strong><small>{s}</small></div>)}</section>
  <div className="mobile-today-strip" aria-label="Today at a glance">{[['Waiting',o.waiting??dash.waiting],['Urgent',o.urgent_waiting??0],['Critical',o.critical_labs??dash.criticalLabs],['Tasks',o.open_tasks??dash.openTasks]].map(([label,value])=><div key={String(label)}><span>{label}</span><strong>{value??0}</strong></div>)}</div>
  <IntelligenceWorkspaceHub token={token} publicMode={publicMode} publicTestPatientNumber={publicTestPatient||undefined} setModule={setModule}/>
  <section className="dashboard-toolbar panel"><div><span className="section-kicker">WORKSPACE VIEW</span><h2>Focus for your role</h2></div><div className="authorized-role-note"><span>AUTHORIZED ROLE</span><strong>{role}</strong></div></section>
  <section className="dashboard-focus-grid">{cards.map(([label,desc,target])=><button className="focus-card panel" key={label} onClick={()=>setModule(target)}><span className="section-kicker">{label.toUpperCase()}</span><strong>{desc}</strong><span>Open workspace →</span></button>)}</section>
  <section className="dashboard-grid">
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">PATIENT FLOW</span><h2>Where people are now</h2></div><button className="ghost" onClick={()=>setModule('queue')}>Open queue</button></div><div className="flow-pipeline">{(intel.queue||[]).slice(0,6).map((x:Row)=><button key={`${x.status}-${x.priority}`} onClick={()=>setModule('queue')}><b>{x.count}</b><span>{pretty(x.status)}</span><small>{x.priority}</small></button>)}{!(intel.queue||[]).length&&<div className="dashboard-empty">No active queue entries yet.</div>}</div></div>
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">CLINICAL ATTENTION</span><h2>Needs review</h2></div></div><div className="attention-list">{(intel.clinical||[]).map((x:Row)=><button key={x.label} onClick={()=>setModule(x.label.includes('laboratory')?'laboratory':x.label.includes('Medication')?'medication-reconciliation':'care-tasks')}><span>{x.label}</span><strong>{x.count}</strong></button>)}</div></div>
  </section>
  <section className="dashboard-grid">
   <div className="panel trend-panel"><div className="panel-title"><div><span className="section-kicker">LAST 7 DAYS</span><h2>Appointments and care activity</h2></div><button className="ghost" onClick={()=>setModule('analytics')}>Full analytics</button></div><div className="trend-chart">{trend.map((x:Row)=><div className="trend-day" key={x.d}><div className="trend-bars"><i style={{height:`${Math.max(8,(Number(x.appointments||0)/maxTrend)*100)}%`}}/><em style={{height:`${Math.max(8,(Number(x.encounters||0)/Math.max(1,maxTrend))*100)}%`}}/></div><small>{String(x.d).slice(5)}</small></div>)}</div><div className="chart-legend"><span><i/>Appointments</span><span><em/>Care visits</span></div></div>
   <div className="panel"><div className="panel-title"><div><span className="section-kicker">FINANCE</span><h2>Revenue at a glance</h2></div><button className="ghost" onClick={()=>setModule('billing')}>Billing</button></div><div className="finance-summary"><div><span>Billed</span><strong>{Number(intel.finance?.billed||0).toLocaleString()} UGX</strong></div><div><span>Paid invoices</span><strong>{intel.finance?.paid||0}</strong></div><div><span>Open invoices</span><strong>{intel.finance?.open||0}</strong></div><div><span>Outstanding</span><strong>{Number(o.outstanding_balance||0).toLocaleString()} UGX</strong></div></div></div>
  </section>
  <section className="panel"><div className="panel-title"><div><span className="section-kicker">FACILITY READINESS</span><h2>Service pressure across facilities</h2></div><button className="ghost" onClick={()=>setModule('district-intelligence')}>District intelligence</button></div><div className="facility-dashboard">{(intel.facilities||[]).map((f:Row)=><button key={f.id} onClick={()=>setModule('facilities')}><div><strong>{f.name}</strong><small>{f.type||'Facility'}</small></div><span><b>{f.occupied_beds}</b> occupied</span><span><b>{f.available_beds}</b> available</span><span className={Number(f.open_incidents)>0?'facility-alert':''}><b>{f.open_incidents}</b> incidents</span></button>)}{!(intel.facilities||[]).length&&<div className="dashboard-empty">Facility readiness will appear here as facilities are configured.</div>}</div></section>
  <section className="command-grid"><div className="panel focus-panel"><div className="panel-title"><div><span className="section-kicker">QUICK ACTIONS</span><h2>Start with what matters</h2></div></div><div className="quick-actions"><button onClick={()=>setModule('patients')}><b>+</b><span><strong>Register patient</strong><small>Start a new patient record</small></span></button><button onClick={()=>setModule('triage')}><b>TR</b><span><strong>Open triage</strong><small>Record vitals and urgency</small></span></button><button onClick={()=>setModule('queue')}><b>Q</b><span><strong>View queue</strong><small>Manage patient flow</small></span></button><button onClick={()=>setModule('appointments')}><b>AP</b><span><strong>Appointments</strong><small>See today's schedule</small></span></button></div></div><div className="panel journey-panel"><div className="panel-title"><div><span className="section-kicker">CARE JOURNEY</span><h2>Patient journey</h2></div><span className="journey-note-inline">{journey.length} steps</span></div><div className="journey-steps">{journey.map(([label,m]:any,i:number)=><button key={label} onClick={()=>setModule(m)}><i>{String(i+1).padStart(2,'0')}</i><span>{label}</span><em>Open</em></button>)}</div><button className="view-all" onClick={()=>setModule('patients')}>Open patient care <span>→</span></button></div></section>
 </div>
}

function IntelligenceWorkspaceHub({token,publicMode,publicTestPatientNumber,setModule}:{token:string;publicMode:boolean;publicTestPatientNumber?:string;setModule:(m:string)=>void}){
 const workspaces=[
  ['patient-360','Patient 360','Longitudinal patient context','patient-360'],
  ['clinical-velocity','Clinical Velocity','Signals, actions and response timing','clinical-velocity'],
  ['value-based-care','Value Based Care','Continuity, outcomes and care gaps','value-based-care'],
  ['ai-risk','AI Risk','Governed clinical and model risk','ai-risk'],
  ['ai-security','AI Security','Security events and protection controls','ai-security'],
  ['ai-governance','AI Governance','Capabilities, evaluations and lifecycle','ai-governance']
 ] as const;
 const [active,setActive]=useState('patient-360');
 const [data,setData]=useState<Row>({});
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState('');
 const [authorizedPatients,setAuthorizedPatients]=useState<Row[]>([]);
 const [selectedPatientId,setSelectedPatientId]=useState('');
 const publicSelectedNumber=publicMode?publicTestPatientNumber||'':'';
 const selectedAuthorizedPatient=authorizedPatients.find((p:Row)=>String(p.id)===selectedPatientId);
 useEffect(()=>{
  if(publicMode||!token){setAuthorizedPatients([]);setSelectedPatientId('');return;}
  let cancelled=false;
  fetch(`${API}/api/patients`,{headers:{Authorization:`Bearer ${token}`}})
   .then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(humanError(d.error||'Patient list could not be loaded'));return d;})
   .then(d=>{
    if(cancelled)return;
    const list=Array.isArray(d.data)?d.data:[];
    setAuthorizedPatients(list);
    setSelectedPatientId(current=>current&&list.some((p:Row)=>String(p.id)===current)?current:String(list[0]?.id||''));
   })
   .catch(()=>{if(!cancelled){setAuthorizedPatients([]);setSelectedPatientId('')}});
  return()=>{cancelled=true};
 },[token,publicMode]);
 const endpointFor=(key:string)=>{
  if(publicMode)return `${API}/api/public/test-intelligence/${key}${key==='patient-360'&&publicSelectedNumber?`?patientNumber=${encodeURIComponent(publicSelectedNumber)}`:''}`;
  const map:Record<string,string>={
   'patient-360':selectedPatientId?`${API}/api/intelligence/patient-360/${encodeURIComponent(selectedPatientId)}`:'',
   'clinical-velocity':`${API}/api/intelligence/clinical-velocity`,
   'value-based-care':`${API}/api/intelligence/value-based-care`,
   'ai-risk':`${API}/api/intelligence/risk-management`,
   'ai-security':`${API}/api/intelligence/security`,
   'ai-governance':`${API}/api/intelligence/lifecycle`
  };
  return map[key];
 };
 useEffect(()=>{
  let cancelled=false;
  async function load(){
   setBusy(true);setError('');
   if(active==='patient-360'&&!publicMode&&!selectedPatientId){setData({selectedPatient:null});setBusy(false);return;}
   try{
    const endpoint=endpointFor(active);
    if(!endpoint){setData({selectedPatient:null});setBusy(false);return;}
    const headers:HeadersInit=token&&!publicMode?{Authorization:`Bearer ${token}`}:{ };
    const r=await fetch(endpoint,{headers});
    const d=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(humanError(d.error||`Unable to load ${pretty(active)}`));
    if(!cancelled)setData(d.data||d||{});
   }catch(e:any){if(!cancelled){setData({});setError(humanError(e.message||'Unable to load intelligence.'));}}
   finally{if(!cancelled)setBusy(false);}
  }
  load();
  return()=>{cancelled=true};
 },[active,publicMode,publicTestPatientNumber,selectedPatientId,token]);
 const arr=(v:any)=>Array.isArray(v)?v:[];
 const selectedTitle=workspaces.find(x=>x[0]===active)?.[1]||'Intelligence';
 const patientContext=data.context||{};
 const patientEvents=arr(patientContext.longitudinalEvents||patientContext.events||patientContext.patientJourney?.events);
 const patientGaps=arr(patientContext.careGaps);
 const patientRisks=arr(patientContext.riskSignals);
 const velocityMetrics=arr(data.metrics||data.velocity?.metrics);
 const valueMeasures=arr(data.measures||data.valueMeasures);
 const riskMatrix=arr(data.riskMatrix);
 const riskSignals=arr(data.clinicalSignals);
 const securityEvents=arr(data.events);
 const controls=arr(data.controls);
 const capabilities=arr(data.capabilities||data.catalog);
 const evaluations=arr(data.evaluations);
 const incidents=arr(data.incidents);
 const lifecycle=arr(data.lifecycle);
 const renderDetail=()=>{
  if(error)return <div className="intelligence-detail-empty"><strong>Intelligence could not be loaded</strong><span>{error}</span><button className="ghost" onClick={()=>setActive(active)}>Retry</button></div>;
  if(busy)return <div className="intelligence-detail-empty"><strong>Loading {selectedTitle}</strong><span>Reading the connected ClinAI records.</span></div>;
  if(active==='patient-360')return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Patient</span><strong>{publicSelectedNumber||selectedAuthorizedPatient?.patientNumber||data.patientNumber||'Select a patient'}</strong></div><div><span>Care events</span><strong>{patientEvents.length||Number(data.context?.patientJourney?.eventCount||0)}</strong></div><div><span>Care gaps</span><strong>{patientGaps.length}</strong></div><div><span>Risk signals</span><strong>{patientRisks.length}</strong></div></div><div className="intelligence-detail-grid"><div><b>Recent care evidence</b>{patientEvents.slice(0,7).map((x:Row,i:number)=><p key={x.id||i}><strong>{x.title||x.eventType||x.kind||x.payload?.title||'Care event'}</strong><small>{x.toState||x.status||x.createdAt||x.at||''}</small></p>)}{!patientEvents.length&&<p className="muted">No recent care events were returned for this patient.</p>}</div><div><b>Care gaps and safety</b>{patientGaps.slice(0,5).map((x:Row,i:number)=><p key={x.id||i}><strong>{x.title||x.gapType||'Care gap'}</strong><small>{x.severity||x.status||''}</small></p>)}{patientRisks.slice(0,4).map((x:Row,i:number)=><p key={`risk-${x.id||i}`}><strong>{x.title||x.riskType||'Risk signal'}</strong><small>{x.severity||x.riskLevel||''}</small></p>)}{!patientGaps.length&&!patientRisks.length&&<p className="muted">No care gaps or risk signals were returned.</p>}</div></div></div>;
  if(active==='clinical-velocity')return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Period</span><strong>{data.periodDays||data.period?.days||30} days</strong></div><div><span>Unresolved signals</span><strong>{Number(data.unresolvedSignals||0)}</strong></div><div><span>Signal groups</span><strong>{velocityMetrics.length}</strong></div><div><span>Guardrails</span><strong>{data.guardrails?.qualitySignalsRequired?'Active':'Not returned'}</strong></div></div><div className="intelligence-table">{velocityMetrics.map((x:Row,i:number)=><div key={i}><b>{pretty(String(x.severity||'signal'))}</b><span>{Number(x.total||0)} signals</span><span>{Number(x.completed||0)} completed</span><span>{x.averageMinutes==null?'—':`${x.averageMinutes} min avg`}</span><span>{Number(x.unresolved||0)} unresolved</span></div>)}{!velocityMetrics.length&&<p className="muted">No workflow timing signals were returned for the selected period.</p>}</div></div>;
  if(active==='value-based-care')return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Measures</span><strong>{valueMeasures.length}</strong></div><div><span>Care gap groups</span><strong>{arr(data.careGapDistribution).length}</strong></div><div><span>Period</span><strong>{data.period?.days||data.periodDays||30} days</strong></div><div><span>Outcome rule</span><strong>Review required</strong></div></div><div className="intelligence-table">{valueMeasures.map((x:Row,i:number)=><div key={i}><b>{pretty(String(x.measure||x.measureCode||'Measure'))}</b><span>Numerator {x.numerator??0}</span><span>Denominator {x.denominator??0}</span><span>{x.valueNumeric==null?'—':`${x.valueNumeric}%`}</span></div>)}{!valueMeasures.length&&<p className="muted">No computable value measures were returned.</p>}</div><p className="intelligence-note">{data.outcomeRule||'Value measures are shown from recorded definitions and events only.'}</p></div>;
  if(active==='ai-risk')return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Risk groups</span><strong>{riskMatrix.length}</strong></div><div><span>Clinical signal groups</span><strong>{riskSignals.length}</strong></div><div><span>Human review</span><strong>Required</strong></div><div><span>Generative role</span><strong>{data.policy?.generativeAIIsInterpretive?'Interpretive':'Governed'}</strong></div></div><div className="intelligence-detail-grid"><div><b>Risk matrix</b>{riskMatrix.slice(0,8).map((x:Row,i:number)=><p key={i}><strong>{pretty(String(x.riskType||'Risk'))}</strong><small>{x.riskLevel||''} · {x.status||''} · {x.count||0}</small></p>)}{!riskMatrix.length&&<p className="muted">No patient-linked AI risk assessments were returned.</p>}</div><div><b>Clinical signals</b>{riskSignals.slice(0,8).map((x:Row,i:number)=><p key={i}><strong>{pretty(String(x.severity||'Signal'))}</strong><small>{x.status||''} · {x.count||0}</small></p>)}{!riskSignals.length&&<p className="muted">No synthetic clinical signal groups were returned.</p>}</div></div></div>;
  if(active==='ai-security')return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Observed events</span><strong>{securityEvents.length}</strong></div><div><span>Controls</span><strong>{controls.length}</strong></div><div><span>Tenant isolation</span><strong>{data.policy?.tenantIsolation?'Active':'Not returned'}</strong></div><div><span>Output protection</span><strong>{data.policy?.unsafeOutputBlocked?'Active':'Not returned'}</strong></div></div><div className="intelligence-detail-grid"><div><b>Recorded events</b>{securityEvents.slice(0,8).map((x:Row,i:number)=><p key={i}><strong>{pretty(String(x.eventType||'Security event'))}</strong><small>{x.severity||''} · {x.status||''} · {x.count||0}</small></p>)}{!securityEvents.length&&<p className="muted">No synthetic security events were recorded in the selected period.</p>}</div><div><b>Protection controls</b>{controls.slice(0,10).map((x:Row,i:number)=><p key={i}><strong>{pretty(String(x.control||'Control'))}</strong><small>{x.status||'Not returned'}</small></p>)}</div></div></div>;
  return <div className="intelligence-detail"><div className="intelligence-stat-row"><div><span>Capabilities</span><strong>{capabilities.length}</strong></div><div><span>Evaluations</span><strong>{evaluations.length}</strong></div><div><span>Incidents</span><strong>{incidents.length}</strong></div><div><span>Lifecycle records</span><strong>{lifecycle.length}</strong></div></div><div className="intelligence-detail-grid"><div><b>Capabilities</b>{capabilities.slice(0,8).map((x:Row,i:number)=><p key={i}><strong>{x.name||x.capabilityId||'Capability'}</strong><small>{x.domain||''} · {x.riskLevel||''} · {x.status||''}</small></p>)}{!capabilities.length&&<p className="muted">No governance capabilities were returned.</p>}</div><div><b>Evaluations and lifecycle</b>{evaluations.slice(0,5).map((x:Row,i:number)=><p key={`eval-${i}`}><strong>{x.capabilityId||'Evaluation'}</strong><small>{x.evaluationType||x.status||''} · {x.count||1}</small></p>)}{incidents.slice(0,5).map((x:Row,i:number)=><p key={`incident-${i}`}><strong>{x.incidentType||'Incident'}</strong><small>{x.severity||''} · {x.status||''} · {x.count||1}</small></p>)}{lifecycle.slice(0,5).map((x:Row,i:number)=><p key={`life-${i}`}><strong>{x.eventType||x.modelId||'Lifecycle event'}</strong><small>{x.environment||''} · {x.outcome||''} · {x.count||1}</small></p>)}{!evaluations.length&&!incidents.length&&!lifecycle.length&&<p className="muted">No governance evaluation, incident or lifecycle records were returned.</p>}</div></div></div>;
 };
 return <section className="panel intelligence-hub"><div className="intelligence-hub-head"><div><span className="section-kicker">INTELLIGENCE WORKSPACES</span><h2>Connected intelligence, from the same records</h2><p>{publicMode?'Six intelligence views are calculated from the synthetic test dataset.':'Six intelligence views use the records available to your authorized workspace.'}</p></div><div className="intelligence-hub-tools">{publicMode?<span className="public-readonly-badge">SYNTHETIC TEST DATA · LIVE REVIEW</span>:<label className="intelligence-patient-picker"><span>Patient 360 patient</span><select aria-label="Choose authorized patient for Patient 360" value={selectedPatientId} onChange={e=>setSelectedPatientId(e.target.value)}><option value="">Select a patient</option>{authorizedPatients.map((p:Row)=><option key={p.id} value={p.id}>{p.patientNumber} · {p.firstName} {p.lastName}</option>)}</select></label>}</div></div><div className="intelligence-workspace-grid">{workspaces.map(([key,title,desc,target])=><button key={key} className={`intelligence-workspace-card ${active===key?'active':''}`} onClick={()=>setActive(key)}><strong>{title}</strong><span>{desc}</span><small>{active===key?'Viewing now':'View workspace'}</small></button>)}</div><div className="intelligence-workspace-detail"><div className="intelligence-detail-head"><div><span className="section-kicker">{selectedTitle.toUpperCase()}</span><h3>{publicMode?(publicSelectedNumber||'Select a test patient'):selectedAuthorizedPatient?.patientNumber||'Connected workspace'}</h3></div><div className="intelligence-detail-source">{publicMode?'Synthetic test data':'Authorized data'}</div></div>{active==='patient-360'&&publicMode&&!publicSelectedNumber&&<div className="intelligence-detail-empty"><strong>Choose a test patient</strong><span>Select one of the synthetic patients above to connect Patient 360 to that record.</span><button className="ghost" onClick={()=>setModule('command-center')}>Open test patients</button></div>}{active==='patient-360'&&!publicMode&&!selectedPatientId&&<div className="intelligence-detail-empty"><strong>Select a patient</strong><span>Choose an authorized patient above to load their Patient 360 context.</span></div>}{(!((active==='patient-360'&&publicMode&&!publicSelectedNumber)||(active==='patient-360'&&!publicMode&&!selectedPatientId)))&&renderDetail()}</div></section>;
}
function DerivedDistrictWorkspace({token,publicWorkspace=false}:{token:string;publicWorkspace?:boolean}){
 const [rows,setRows]=useState<Row[]>([]); const [error,setError]=useState('');
 const load=async()=>{try{const r=await fetchJSON(`${API}/api/district-intelligence`,{},token);if(!r.r.ok)throw new Error(r.data?.error||'District intelligence could not be loaded');setRows(r.data?.data||[])}catch(e:any){setError(humanError(e.message))}};
 useEffect(()=>{if(token)load()},[token]);
 return <section className="workspace-panel panel"><div className="panel-title"><div><span className="section-kicker">OPERATIONS INTELLIGENCE</span><h2>District intelligence</h2><p>Facility coverage, operational incidents and workforce signals from configured districts.</p></div><button className="ghost" onClick={load}>↻ Refresh</button></div>{error&&<div className="error">{error}</div>}<div className="intelligence-card-grid">{rows.map(r=><article className="intelligence-card" key={r.id}><span>{r.name}</span><strong>{r.facilityCount||0}</strong><small>{r.openIncidents||0} open incidents · {r.recentWorkforceSnapshots||0} workforce snapshots</small></article>)}</div>{!rows.length&&!error&&<div className="workspace-empty"><strong>No district records yet</strong><span>Create districts and facility links to activate this operational dashboard.</span></div>}</section>
}

function IntelligenceSummary({module,rows}:{module:string;rows:Row[]}){
 const x=rows[0]||{};
 const cards:Record<string,Array<[string,any]>>={
  'clinical-velocity':[['Period',`${x.periodDays||30} days`],['Orders created',x.metrics?.ordersCreated||0],['Results available',x.metrics?.resultsAvailable||0],['Referral closure rate',x.metrics?.referralClosureRate==null?'—':`${x.metrics.referralClosureRate}%`],['Tasks completed',x.metrics?.tasksCompleted||0]],
  'value-based-care':[['Period',`${x.periodDays||30} days`],['Completed follow-ups',x.outcomes?.completedFollowups||0],['Completed referrals',x.outcomes?.completedReferrals||0],['Critical results released',x.outcomes?.criticalResultsReleased||0],['Gap groups',x.careGapProfile?.length||0]],
  'ai-risk-management':[['Clinical signal groups',x.clinicalSignals?.length||0],['AI risk groups',x.aiRiskAssessments?.length||0],['Human review',x.policy?.deterministicSignalsRemainSourceOfClinicalRisk?'Required':'Review policy'],['Generative AI role',x.policy?.generativeAIIsInterpretive?'Interpretive':'Governed']],
  'ai-security-management':[['Security events',rows.length],['Latest event',x.createdAt||'None'],['Severity',x.severity||'Info'],['Status',x.status||'Observed']],
  'patient-360-intelligence':[['Open care gaps',x.careGaps?.length||0],['Risk signals',x.riskSignals?.length||0],['Velocity events',x.velocity?.eventProfile?.length||0],['Governance capabilities',x.governance?.capabilities?.length||0]],
  'ai-governance':[['Capabilities',x.capabilities?.length||0],['Risk groups',x.risks?.length||0],['Security groups',x.securityEvents?.length||0],['Evaluation groups',x.evaluations?.length||0]],
 };
 const selected=cards[module]||[];
 return <div className="intelligence-summary"><div className="intelligence-card-grid">{selected.map(([label,value])=><div className="intelligence-card" key={label}><span>{label}</span><strong>{String(value)}</strong></div>)}</div><p className="intelligence-note">ClinAI brings together recorded information and review signals so teams can focus on what may need attention.</p></div>
}

function ModuleDataDashboard({module,rows}:{module:string;rows:Row[]}){const total=rows.length;const patients=new Set(rows.map(r=>r.patientId||r.patient_id).filter(Boolean)).size;const open=rows.filter(r=>['open','active','pending','in-review','urgent','in-progress','scheduled'].includes(String(r.status||'').toLowerCase())).length;const critical=rows.filter(r=>['critical','urgent'].includes(String(r.priority||r.severity||'').toLowerCase())).length;const latest=rows.map(r=>r.createdAt||r.updatedAt||r.created_at||r.updated_at).filter(Boolean).sort().at(-1);return <section className="module-data-dashboard" aria-label={`${pretty(module)} dashboard`}><div><span>Total records</span><strong>{total.toLocaleString()}</strong><small>Recorded information in this view</small></div><div><span>Patients represented</span><strong>{patients.toLocaleString()}</strong><small>Patients represented</small></div><div><span>Open / active</span><strong>{open.toLocaleString()}</strong><small>Open or active care</small></div><div><span>Priority signals</span><strong>{critical.toLocaleString()}</strong><small>Priority records</small></div><div><span>Latest activity</span><strong>{latest?new Date(latest).toLocaleDateString():'—'}</strong><small>Most recent activity</small></div></section>}


