 const sections=['Patient & context','Clinical details','Status & timing','Details'].filter(s=>fs.some(f=>fieldGroup(f.key,f.type)===s||(f as any).section===s));
 const renderField=(f:ContractField)=>{const err=errors[f.key];const fieldLabel=f.label||pretty(f.key);const displayLabel=friendlyFieldLabel(fieldLabel);if(module==='documents'&&(f.key==='mimeType'||f.key==='metadata'))return null;if(module==='documents'&&f.key==='storageRef')return <label key={f.key} className="field-wide"><span>Document file *</span><input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.txt,.csv,.xls,.xlsx,application/pdf,image/*" required onChange={e=>chooseDocument(e.target.files?.[0]||null)}/><small className="field-hint">Select the patient document. The file name, type and storage reference are captured automatically.</small>{documentFile&&<small className="field-hint">Selected: {documentFile.name} · {(documentFile.size/1024).toFixed(1)} KB</small>}{err&&<small className="field-error">{err}</small>}</label>;const isRef=f.type==='uuid'&&(/patientId|facilityId|fromFacilityId|toFacilityId/.test(f.key));const options=isRef?(f.key==='patientId'?refOptions.patientId:refOptions.facilities):undefined;return <label key={f.key} className={(f.type==='json'||f.type==='textarea')?'field-wide':''}><span>{displayLabel}{f.required?' *':''}</span>{f.options?<select aria-invalid={!!err} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}><option value="">Select {displayLabel.toLowerCase()}</option>{f.options.map(o=><option key={o} value={o}>{pretty(o)}</option>)}</select>:isRef&&options?.length?<select aria-invalid={!!err} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}><option value="">Select {displayLabel.toLowerCase()}</option>{options.map((o:Row)=><option key={o.id} value={o.id}>{o.patientNumber?`${o.patientNumber} · ${o.firstName||''} ${o.lastName||''}`:o.name||o.id}</option>)}</select>:f.type==='boolean'?<select aria-invalid={!!err} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}><option value="">Select</option><option value="true">Yes</option><option value="false">No</option></select>:f.type==='json'?<textarea className="structured-editor" aria-invalid={!!err} rows={4} placeholder={`Enter ${displayLabel.toLowerCase()}`} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}/>:f.type==='textarea'?<textarea aria-invalid={!!err} rows={4} placeholder={f.placeholder||fieldLabel} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}/>:<input aria-invalid={!!err} required={f.required} type={f.type==='datetime'?'datetime-local':f.type||'text'} placeholder={f.placeholder||fieldLabel} value={d[f.key]??''} onChange={e=>updateField(f.key,e.target.value)}/>}<small className="field-hint">{f.type==='uuid'?'Select a related record.':f.required?'Required field.':'Optional field.'}</small>{err&&<small className="field-error">{err}</small>}</label>};
