   let out=text.trim();
   const names=[...hs,'CURRENT SITUATION','RECORDED FACTS','CARE GAPS','CROSS-MODULE EVIDENCE','SAFETY SIGNALS','CALCULATIONS','SUGGESTED NEXT CHECKS','PROVENANCE'];
   for(const name of names){const re=new RegExp(`^(?:\\*\\*)?${name.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\$&')}(?:\\*\\*)?(?:\\s+|[:：])*`,'i');out=out.replace(re,'').trim();}
