 add(hs[0],direct);add(hs[1],j.recordedFacts);add(hs[2],j.attentionItems?.length?j.attentionItems:j.suggestedReview);add('CARE GAPS',j.careGaps);add('CROSS-MODULE EVIDENCE',j.crossModuleEvidence?.length?j.crossModuleEvidence:j.evidence);add('SAFETY SIGNALS',j.safetySignals);add('SUGGESTED NEXT CHECKS',j.suggestedReview);add(hs[3],j.uncertainty);
